create extension if not exists pg_trgm; create extension if not exists unaccent;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,staff_code text unique,full_name text,email text,role text not null default 'viewer' check(role in('admin','finance_manager','data_entry','reviewer','viewer')),active boolean not null default true,last_seen_at timestamptz);
create table if not exists public.revenue_lines(code text primary key,name text not null,active boolean not null default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.students(id bigint generated always as identity primary key,index_number text not null unique,student_name text not null,programme text,level text,cohort text,revenue_line_code text references public.revenue_lines(code),opening_balance numeric(14,2) not null default 0,normalized_name text,normalized_index text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists students_norm_name_trgm on students using gin(normalized_name gin_trgm_ops); create index if not exists students_norm_index on students(normalized_index);
create table if not exists public.payments(id bigint generated always as identity primary key,payment_date date not null,payer_name text not null,index_number text,amount numeric(14,2) not null check(amount>0),bank_reference text not null,revenue_line_code text references public.revenue_lines(code),batch_id text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),matched_student_id bigint references public.students(id),match_score numeric(5,4),match_status text not null default 'unprocessed' check(match_status in('unprocessed','auto_posted','review','approved','unidentified')),match_method text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz);
create index if not exists payments_student_idx on payments(matched_student_id); create index if not exists payments_status_idx on payments(match_status); create index if not exists payments_batch_idx on payments(batch_id); create index if not exists payments_date_idx on payments(payment_date);
create table if not exists public.audit_log(id bigint generated always as identity primary key,created_at timestamptz not null default now(),user_id uuid references auth.users(id),staff_code text,action text not null,module text not null,record_id text,batch_id text,details jsonb default '{}'::jsonb);
create index if not exists audit_created_idx on audit_log(created_at desc); create index if not exists audit_staff_idx on audit_log(staff_code);
create or replace function public.norm_text(t text) returns text language sql immutable as $$select regexp_replace(lower(unaccent(coalesce(t,''))),'[^a-z0-9]','','g')$$;
create or replace function public.set_normalized_student() returns trigger language plpgsql as $$begin new.normalized_name:=public.norm_text(new.student_name);new.normalized_index:=public.norm_text(new.index_number);new.updated_at:=now();if new.created_by is null then new.created_by:=auth.uid();end if;return new;end$$;
drop trigger if exists trg_student_norm on students; create trigger trg_student_norm before insert or update on students for each row execute function public.set_normalized_student();
create or replace function public.current_role() returns text language sql stable as $$select role from profiles where id=auth.uid() and active=true limit 1$$;
create or replace function public.audit_row() returns trigger language plpgsql security definer set search_path=public as $$declare rid text;bid text;begin rid=coalesce((to_jsonb(new)->>'id'),(to_jsonb(old)->>'id'));bid=coalesce((to_jsonb(new)->>'batch_id'),(to_jsonb(old)->>'batch_id'));insert into audit_log(user_id,staff_code,action,module,record_id,batch_id,details)values(auth.uid(),(select staff_code from profiles where id=auth.uid()),TG_OP,TG_TABLE_NAME,rid,bid,jsonb_build_object('new',to_jsonb(new),'old',to_jsonb(old)));return coalesce(new,old);end$$;
drop trigger if exists trg_audit_payment on payments; create trigger trg_audit_payment after insert or update or delete on payments for each row execute function public.audit_row(); drop trigger if exists trg_audit_student on students; create trigger trg_audit_student after insert or update or delete on students for each row execute function public.audit_row(); drop trigger if exists trg_audit_revenue on revenue_lines; create trigger trg_audit_revenue after insert or update or delete on revenue_lines for each row execute function public.audit_row();
insert into revenue_lines(code,name) values('TUITION','Tuition Fees'),('HOSTEL','Hostel Fees'),('EXAM','Examination Fees'),('MISC','Other Student Revenue') on conflict(code) do nothing;
create or replace function public.match_unresolved_payments(p_limit int default 5000) returns table(processed_count int,auto_posted int,reviewed int,unidentified int) language plpgsql as $$begin with todo as(select id,payer_name,index_number from payments where match_status='unprocessed' order by id limit p_limit),best as(select p.id,s.id sid,greatest(case when public.norm_text(p.index_number)<>'' and public.norm_text(p.index_number)=s.normalized_index then 1.0 else 0 end,case when public.norm_text(p.payer_name)<>'' and public.norm_text(p.payer_name)=s.normalized_name then 0.99 else 0 end,similarity(public.norm_text(p.payer_name),s.normalized_name)*0.85+case when public.norm_text(p.index_number)<>'' and public.norm_text(p.index_number)=s.normalized_index then 0.15 else 0 end) score,case when public.norm_text(p.index_number)<>'' and public.norm_text(p.index_number)=s.normalized_index then 'exact_index' when public.norm_text(p.payer_name)=s.normalized_name then 'exact_name' else 'fuzzy_name' end method from todo p join lateral(select * from students s where (public.norm_text(p.index_number)<>'' and public.norm_text(p.index_number)=s.normalized_index) or s.normalized_name % public.norm_text(p.payer_name) order by case when public.norm_text(p.index_number)<>'' and public.norm_text(p.index_number)=s.normalized_index then 1 else 0 end desc,similarity(public.norm_text(p.payer_name),s.normalized_name) desc limit 1)s on true) update payments p set matched_student_id=b.sid,match_score=b.score,match_method=b.method,match_status=case when b.score>=0.92 then 'auto_posted' when b.score>=0.75 then 'review' else 'unidentified' end from best b where p.id=b.id; update payments set match_status='unidentified' where id in(select id from todo) and match_status='unprocessed'; return query select count(*)::int,count(*) filter(where match_status='auto_posted')::int,count(*) filter(where match_status='review')::int,count(*) filter(where match_status='unidentified')::int from payments where id in(select id from todo);end$$;
create or replace view public.student_debtors_view as select s.id,s.index_number,s.student_name,s.programme,s.level,s.cohort,s.revenue_line_code,s.opening_balance,coalesce(sum(p.amount) filter(where p.match_status in('auto_posted','approved')),0)::numeric(14,2) total_paid,(s.opening_balance-coalesce(sum(p.amount) filter(where p.match_status in('auto_posted','approved')),0))::numeric(14,2) closing_balance,count(p.id) filter(where p.match_status in('auto_posted','approved')) payment_count from students s left join payments p on p.matched_student_id=s.id group by s.id;
create or replace function public.dashboard_metrics() returns table(opening_debtors numeric,total_payments numeric,closing_debtors numeric,overpaid_amount numeric,review_count bigint,unidentified_count bigint,overpaid_students bigint,unpaid_students bigint) language sql as $$select coalesce(sum(opening_balance),0),coalesce((select sum(amount) from payments where match_status in('auto_posted','approved')),0),coalesce(sum(closing_balance),0),coalesce(sum(greatest(-closing_balance,0)),0),(select count(*) from payments where match_status='review'),(select count(*) from payments where match_status='unidentified'),count(*) filter(where closing_balance<0),count(*) filter(where opening_balance>0 and closing_balance=opening_balance) from student_debtors_view$$;
create or replace function public.revenue_summary() returns table(code text,name text,opening_debtors numeric,collections numeric,closing_debtors numeric) language sql as $$select r.code,r.name,coalesce(sum(s.opening_balance),0),coalesce(sum(p.amount) filter(where p.match_status in('auto_posted','approved')),0),coalesce(sum(s.opening_balance),0)-coalesce(sum(p.amount) filter(where p.match_status in('auto_posted','approved')),0) from revenue_lines r left join students s on s.revenue_line_code=r.code left join payments p on p.matched_student_id=s.id where r.active group by r.code,r.name order by r.code$$;
create or replace function public.review_queue() returns table(id bigint,payment_date date,payer_name text,index_number text,amount numeric,bank_reference text,revenue_line_code text,batch_id text,match_score numeric,match_method text,created_at timestamptz) language sql as $$select id,payment_date,payer_name,index_number,amount,bank_reference,revenue_line_code,batch_id,match_score,match_method,created_at from payments where match_status='review' order by created_at desc$$;
create or replace function public.overpaid_students() returns table(index_number text,student_name text,opening_balance numeric,total_paid numeric,closing_balance numeric) language sql as $$select index_number,student_name,opening_balance,total_paid,closing_balance from student_debtors_view where closing_balance<0 order by closing_balance$$;
create or replace function public.unpaid_students() returns table(index_number text,student_name text,opening_balance numeric,total_paid numeric,closing_balance numeric) language sql as $$select index_number,student_name,opening_balance,total_paid,closing_balance from student_debtors_view where opening_balance>0 and closing_balance=opening_balance order by opening_balance desc$$;
create or replace function public.unidentified_payments() returns table(id bigint,payment_date date,payer_name text,index_number text,amount numeric,bank_reference text,revenue_line_code text,batch_id text,match_score numeric,match_method text,created_at timestamptz) language sql as $$select id,payment_date,payer_name,index_number,amount,bank_reference,revenue_line_code,batch_id,match_score,match_method,created_at from payments where match_status='unidentified' order by created_at desc$$;
alter table profiles enable row level security;alter table revenue_lines enable row level security;alter table students enable row level security;alter table payments enable row level security;alter table audit_log enable row level security;
create policy profiles_read on profiles for select to authenticated using(id=auth.uid() or public.current_role() in('admin','finance_manager'));create policy profiles_update on profiles for update to authenticated using(id=auth.uid() or public.current_role() in('admin','finance_manager')) with check(id=auth.uid() or public.current_role() in('admin','finance_manager'));
create policy revenue_read on revenue_lines for select to authenticated using(true);create policy revenue_insert on revenue_lines for insert to authenticated with check(public.current_role() in('admin','finance_manager'));create policy revenue_update on revenue_lines for update to authenticated using(public.current_role() in('admin','finance_manager')) with check(public.current_role() in('admin','finance_manager'));
create policy students_read on students for select to authenticated using(true);create policy students_insert on students for insert to authenticated with check(public.current_role() in('admin','finance_manager','data_entry'));
create policy payments_read on payments for select to authenticated using(true);create policy payments_insert on payments for insert to authenticated with check(public.current_role() in('admin','finance_manager','data_entry'));create policy payments_update on payments for update to authenticated using(public.current_role() in('admin','finance_manager','reviewer')) with check(public.current_role() in('admin','finance_manager','reviewer'));
create policy audit_read on audit_log for select to authenticated using(public.current_role() in('admin','finance_manager','reviewer'));create policy audit_block on audit_log for insert to authenticated with check(false);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,email,full_name,role,active)values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',new.email),'viewer',true)on conflict(id)do nothing;return new;end$$;drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();